effect.shader:
// tempo do Node ligado ao motor (tools/nodevideo/ligar_tempo.py)
#define _cur_time acTime
vec4 u_xlat0;
vec4 u_xlat1;
vec3 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat7;
bool u_xlatb7;
bvec2 u_xlatb13;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.xy = acScreenNorm.xy + vec2(4.0, 4.0);
    u_xlat1.x = u_xlat1.y * u_xlat1.x;
    u_xlat7.x = _cur_time * 10.0 + 100.0;
    u_xlat1.x = u_xlat7.x * u_xlat1.x;
    u_xlat1.xy = u_xlat1.xx * vec2(0.0769230798, 0.008130081);
    u_xlatb13.xy = greaterThanEqual(u_xlat1.xyxy, (-u_xlat1.xyxy)).xy;
    u_xlat1.xy = fract(abs(u_xlat1.xy));
    {
        vec4 hlslcc_movcTemp = u_xlat1;
        hlslcc_movcTemp.x = (u_xlatb13.x) ? u_xlat1.x : (-u_xlat1.x);
        hlslcc_movcTemp.y = (u_xlatb13.y) ? u_xlat1.y : (-u_xlat1.y);
        u_xlat1 = hlslcc_movcTemp;
    }
    u_xlat1.xy = u_xlat1.xy * vec2(13.0, 123.0) + vec2(1.0, 1.0);
    u_xlat1.x = u_xlat1.y * u_xlat1.x;
    u_xlat1.x = u_xlat1.x * 100.0;
    u_xlatb7 = u_xlat1.x>=(-u_xlat1.x);
    u_xlat1.x = fract(abs(u_xlat1.x));
    u_xlat1.x = (u_xlatb7) ? u_xlat1.x : (-u_xlat1.x);
    u_xlat1.x = u_xlat1.x * 0.00999999978 + -0.00499999989;
    u_xlat7.x = (-u_xlat1.x) * _amount + 1.0;
    u_xlat7.xyz = u_xlat0.xyz * u_xlat7.xxx;
    u_xlat2.xyz = u_xlat1.xxx * vec3(_amount) + u_xlat0.xyz;
    u_xlat1.xyz = (int(_blend_mode) != 0) ? u_xlat2.xyz : u_xlat7.xyz;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat1.w = u_xlat0.w;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat5 = u_xlat0 * u_xlat5;
        u_xlat3 = u_xlat3 * u_xlat4 + u_xlat5;
        u_xlat0.x = u_xlat4.x * u_xlat3.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat0.x : u_xlat3.w;
        fragColor.xyz = u_xlat3.xyz;
    } else {
        fragColor.xyz = u_xlat1.xyz;
        fragColor.w = u_xlat0.w;
    }
    return;
}
